import*as T from'three';import{createToyKit}from'../world/toy-kit.js';import{AIRPORT_APPROACHES}from'./layout.js';
export function buildAirportEntrance(parent,parentRoomId){const e=AIRPORT_APPROACHES.find(e=>e.parentRoomId===parentRoomId);if(!e)throw new RangeError('Unknown airport approach');const root=new T.Group();root.name=parentRoomId+'.airport-entrance';parent.add(root);const kit=createToyKit(root),village=parentRoomId==='courtyard',start=village?10:0,end=e.at.x,surfaceY=village?.0501:.0221,paintY=village?.0504:.0224;if(village)kit.box(Math.abs(end-start),.0002,1.4,'#eadcc0',(start+end)/2,surfaceY,e.at.z,.00005).name='airport.parent-path';else for(let i=1;i<e.points.length;i++){const a=e.points[i-1],b=e.points[i],dx=b[0]-a[0],dz=b[1]-a[1],horizontal=Math.abs(dx)>=Math.abs(dz),mesh=kit.box(horizontal?Math.abs(dx):1.4,.0002,horizontal?1.4:Math.abs(dz),'#eadcc0',(a[0]+b[0])/2,surfaceY,(a[1]+b[1])/2,.00005);mesh.name='airport.parent-path.'+i;}kit.box(.36,.0002,1.4,'#aac8ba',end,paintY,e.at.z,.00005).name='airport.parent-threshold';const sign=new T.Group();sign.name=e.sign.id;sign.userData.label=village?'작은 공항 · 구름섬행':'작은 공항 · 별빛 마을행';sign.position.set(e.sign.x,0,e.sign.z);root.add(sign);if(e.sign.flat){kit.box(e.sign.hx*2,.0002,e.sign.hz*2,'#f4e9cf',0,paintY,0,.00005,sign).name='airport.floor-pictogram.mat';kit.box(.09,.0002,.76,'#527b79',0,paintY+.00025,0,.00005,sign).name='airport.floor-pictogram.fuselage';kit.box(.78,.0002,.11,'#527b79',0,paintY+.00025,-.06,.00005,sign).name='airport.floor-pictogram.wings';kit.box(.30,.0002,.08,'#527b79',0,paintY+.00025,.28,.00005,sign).name='airport.floor-pictogram.tail';return root;}kit.cylinder(.035,.045,1.12,'#b99c7c',0,.61,0,sign);kit.box(e.sign.hx*2,.43,e.sign.hz*2,'#f4e9cf',0,1.20,0,.06,sign);const front=e.sign.hz+.015;kit.box(.045,.27,.02,'#698c86',0,1.20,front,.008,sign);kit.box(.33,.055,.02,'#698c86',0,1.21,front,.008,sign);kit.box(.14,.038,.02,'#698c86',0,1.105,front,.008,sign);return root;}
